raiz = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')
os.makedirs(os.path.join(raiz, 'telao', 'i18n'), exist_ok=True)
for i, l in enumerate(('en', 'fr', 'de')):
    json.dump({k: v[i] for k, v in C.items()}, open(os.path.join(raiz, 'telao', 'i18n', l + '.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
    trad = {}
    for f in sorted(glob.glob(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'saida', 'lote*.json'))):
        for cod, v in json.load(open(f, encoding='utf-8')).items():
            if l in v:
                trad[cod] = {k: x for k, x in v[l].items() if x}
    json.dump(trad, open(os.path.join(raiz, 'telao', 'dados', f'trad-{l}.json'), 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
    print(l, len(C), len(trad))
